import { SCHEMA } from './name'
import { expiresAtMs, isWarm, sessionRatio, totalInputTokens } from './cache'
import type { RateLimit, Snap } from './types'

export type Event =
  | 'session.start' | 'session.clear' | 'session.resume' | 'session.fork' | 'turn.complete'
  | 'rate-limit' | 'model' | 'cwd' | 'branch' | 'pr' | 'cache.cold' | 'compact' | 'session.end'

/** `claude-opus-5-5[1m]` -> `{ id: 'claude-opus-5-5', display_name: 'Opus 5.5' }`. */
export function modelOf(raw: string): { id: string; display_name: string } {
  const id = raw.replace(/\[[^\]]*\]$/, '')
  const m = /^claude-(opus|sonnet|haiku|fable)-(\d+)-(\d+)/.exec(id)
  const name = m ? `${(m[1] ?? '').charAt(0).toUpperCase()}${(m[1] ?? '').slice(1)} ${m[2]}.${m[3]}` : id
  return { id, display_name: name }
}

/** ISO `resetsAt` and decimal `percentUsed` to census's windows: epoch SECONDS, or census drops it. */
export function rateLimitsOf(limits: RateLimit[]): Record<string, { used_percentage: number; resets_at: number }> {
  const out: Record<string, { used_percentage: number; resets_at: number }> = {}
  for (const l of limits) {
    const ms = l.resetsAt ? Date.parse(l.resetsAt) : Number.NaN
    if (!Number.isFinite(ms) || !Number.isFinite(l.percentUsed)) continue
    out[l.kind] = { used_percentage: l.percentUsed, resets_at: Math.floor(ms / 1000) }
  }
  return out
}

/**
 * The status-line payload shape census reads, plus `census_mod`. `now` in ms. Keys census does not
 * know are stored verbatim, so every extra here is free; a key this cannot fill is OMITTED, not
 * faked (census keeps the prior value of a null, and drops a half-formed window).
 */
export function buildPayload(s: Snap, now: number, event: Event, ended?: string): Record<string, unknown> {
  const c = s.counters
  const expires = expiresAtMs(c, s.ttl)
  const cache: Record<string, unknown> = {
    warm: isWarm(c, s.ttl, now),
    ttl: s.ttl,
    requests: c.requests,
  }
  if (expires !== null) cache.expires_at = Math.floor(expires / 1000)
  if (c.lastRatio !== null) cache.hit_ratio = c.lastRatio
  const whole = sessionRatio(c)
  if (whole !== null) cache.session_hit_ratio = whole

  const p: Record<string, unknown> = { session_id: s.sessionId }
  if (s.transcriptPath) p.transcript_path = s.transcriptPath
  p.cwd = s.cwd
  // No project_dir: the mod tracks the current directory, not a project root, and would go stale after a cd.
  p.workspace = { current_dir: s.cwd }
  if (s.worktreePath) p.worktree = { path: s.worktreePath }
  if (s.model) p.model = s.model
  p.context_window = {
    used_percentage: s.ctxPct,
    ...(s.ctxWindow !== null ? { context_window_size: s.ctxWindow } : {}),
    total_input_tokens: totalInputTokens(c),
    total_output_tokens: c.output,
  }
  const cost: Record<string, number> = {}
  if (s.costUsd !== null) cost.total_cost_usd = s.costUsd
  if (s.startedAt !== null) cost.total_duration_ms = Math.max(0, Math.round(now - s.startedAt))
  p.cost = cost
  const limits = rateLimitsOf(s.rateLimits)
  if (Object.keys(limits).length) p.rate_limits = limits
  p.prompt_cache = cache
  if (s.sessionName) p.session_name = s.sessionName
  if (s.pr) p.pr = { number: s.pr.number, url: s.pr.url, ...(s.pr.reviewState ? { review_state: s.pr.reviewState } : {}) }
  if (s.version) p.version = s.version
  p.census_mod = {
    version: SCHEMA,
    ...(s.proc ? { pid: s.proc.pid, proc_start: s.proc.procStart } : {}),
    event,
    ...(ended !== undefined ? { ended } : {}),
    // The `-uno` git pass, in gitcache's field names, so readers never shell out to git themselves.
    git: s.git ? { branch: s.git.branch, uncommitted: s.git.uncommitted, ahead: s.git.ahead, has_upstream: s.git.hasUpstream, detached: s.git.detached } : null,
  }
  return p
}

files.core/registry.ts:
import type { Proc } from './types'

/**
 * Claude Code's own session registry holds `<config dir>/sessions/<pid>.json` per live process,
 * with the `procStart` string (ps lstart text, in another zone: only ever compared as a string)
 * and the version. The entry whose `sessionId` is ours names our process.
 */
export function findProc(files: { text: string }[], sessionId: string): Proc | null {
  for (const f of files) {
    let d: unknown
    try {
      d = JSON.parse(f.text)
    } catch {
      continue
    }
    if (!d || typeof d !== 'object' || Array.isArray(d)) continue // null, a scalar or an array is no registry entry
    const r = d as { pid?: unknown; sessionId?: unknown; procStart?: unknown; version?: unknown }
    if (r.sessionId !== sessionId || typeof r.pid !== 'number' || r.pid <= 1 || typeof r.procStart !== 'string') continue
    return { pid: r.pid, procStart: r.procStart, ...(typeof r.version === 'string' ? { version: r.version } : {}) }
  }
  return null
}

/** The last `custom-title` row of `grep -F '"type":"custom-title"'` output. */
export function lastTitle(stdout: string): string | null {
  const lines = stdout.split('\n').filter(l => l.includes('"custom-title"'))
  for (let i = lines.length - 1; i >= 0; i--) {
    try {
      const t = (JSON.parse(lines[i] ?? '') as { customTitle?: unknown }).customTitle
      if (typeof t === 'string' && t.trim()) return t.trim()
    } catch {
      // a row cut mid-write; try the one before
    }
  }
  return null
}

/** The whole transcript, once per bound session. */
export const TITLE_ARGV = (path: string): string[] => ['grep', '-h', '-F', '"type":"custom-title"', path]
/** After each turn: only the tail, where a later /rename lands, so a long session is not re-read whole every turn. */
export const TITLE_TAIL_CMD = 'tail -c 262144 "$1" | grep -F \'"type":"custom-title"\''

files.core/render.ts:
// The status line as data: a port of census's render.py (segments, glyphs, thresholds, the `/` line
// syntax). A line is a list of runs; the shell turns runs into <Text>, tests read them as text.
import type { GitState, Pr } from './types'

export type Tone = 'grey' | 'cyan' | 'green' | 'yellow' | 'magenta' | 'pac' | 'white' | 'red' | 'orange' | 'claude'
export type Run = { t: string; tone?: Tone; bold?: boolean }
export type Line = Run[]

/** render.py's ANSI palette as Text colours (names the surface's chalk-style colours accept; orange is 256-colour 208). */
export const TONE_COLOR: Record<Tone, string> = {
  grey: 'gray', cyan: 'cyan', green: 'green', yellow: 'yellow', magenta: 'magenta',
  pac: 'yellowBright', white: 'whiteBright', red: 'red', orange: '#ff8700',
  claude: '#D97757', // the asterisk's own orange (proven live as a raw hex Text colour)
}

export type RenderEnv = {
  CENSUS_STATUSLINE_SEGMENTS?: string
  CENSUS_STATUSLINE_MASCOT?: string
  CLAUDE_COST_BUDGET?: string
  CLAUDE_PROFILE?: string
  CLAUDE_CONFIG_DIR?: string
}

export type RenderInput = {
  now: number // epoch seconds
  ctxPct: number | null
  cache: { hitRatio: number | null; requests: number; warm: boolean; expiresAt: number | null; misses: number }
  limits: Record<string, { used_percentage: number; resets_at: number } | undefined>
  /** The context window's size in tokens, when known (the Clean preset shows used/size). */
  ctxWindow?: number | null
  costUsd: number | null
  durationMs: number | null
  modelName: string | null
  git: Pick<GitState, 'branch' | 'uncommitted' | 'ahead' | 'hasUpstream'> | null
  pr: Pr | null
  cwd: string
  env: RenderEnv
}

export const DEFAULT_SEGMENTS = 'context,cache,limits,cost/model,git,dir,changes,pr'
export const DEFAULT_BUDGET = 20
export const BAR_WIDTH = 10

/** printf "%.0f": round half to even. */
export function roundHalfEven(x: number): number {
  const f = Math.floor(x)
  const d = x - f
  if (d < 0.5) return f
  if (d > 0.5) return f + 1
  return f % 2 === 0 ? f : f + 1
}

export const levelTone = (pct: number): Tone => (pct >= 90 ? 'red' : pct >= 75 ? 'orange' : 'green')
export const levelToneInv = (pct: number): Tone => (pct >= 90 ? 'green' : pct >= 75 ? 'orange' : 'red')

export function pacBar(pct: number, width = BAR_WIDTH, glyph = '•', ahead?: string): Run[] {
  const track = ahead ?? glyph
  const filled = Math.max(0, Math.min(Math.floor((pct / 100) * width + 0.5), width))
  const pac = Math.min(filled, width - 1)
  const out: Run[] = []
  for (let j = 0; j < width; j++) {
    if (j < pac) out.push({ t: glyph, tone: levelTone(Math.floor(((j + 1) * 100) / width)) })
    else if (j === pac) out.push({ t: 'ᗧ', tone: 'pac' })
    else out.push({ t: track, tone: 'white' })
  }
  return out
}

export function fmtReset(target: number, now: number): string {
  const diff = Math.max(0, Math.floor(target - now))
  if (diff >= 86400) return `${Math.floor(diff / 86400)}d${Math.floor((diff % 86400) / 3600)}h`
  if (diff >= 3600) return `${Math.floor(diff / 3600)}h${Math.floor((diff % 3600) / 60)}m`
  return `${Math.floor(diff / 60)}m`
}

const sp: Run = { t: ' ' }
const grey = (t: string): Run => ({ t, tone: 'grey' })

function segContext(i: RenderInput): Line[] {
  if (i.ctxPct === null) {
    return [[grey('🧠'), sp, { t: 'ᗧ', tone: 'pac' }, { t: '•'.repeat(BAR_WIDTH - 1), tone: 'white' }, sp, grey('--%')]]
  }
  const shown = roundHalfEven(i.ctxPct)
  return [[grey('🧠'), sp, ...pacBar(i.ctxPct), sp, { t: `${shown}%`, tone: levelTone(shown) }]]
}

function segCache(i: RenderInput): Line[] {
  const { hitRatio, requests, warm, expiresAt, misses } = i.cache
  if (hitRatio === null || !(requests > 0)) return []
  const pct = roundHalfEven(Math.max(0, Math.min(100, hitRatio * 100)))
  const line: Line = [grey(warm ? '🎯' : '🧊'), sp, { t: `${pct}%`, tone: levelToneInv(pct) }]
  if (warm && expiresAt !== null) line.push(sp, grey(`⟳ ${fmtReset(expiresAt, i.now)}`))
  if (misses > 0) line.push(sp, { t: `✗${misses}`, tone: 'red' })
  return [line]
}

function usageBar(i: RenderInput, w: { used_percentage: number; resets_at: number }): Line {
  const shown = roundHalfEven(w.used_percentage)
  return [...pacBar(w.used_percentage), sp, { t: `${shown}%`, tone: levelTone(shown) }, sp, grey(`⟳ ${fmtReset(w.resets_at, i.now)}`)]
}

function segLimits(i: RenderInput): Line[] {
  const out: Line[] = []
  for (const [key, emoji] of [['five_hour', '⏳'], ['seven_day', '📅']] as const) {
    const w = i.limits[key]
    if (!w) continue
    if (w.resets_at <= i.now) continue // an expired window is a fossil
    out.push([grey(emoji), sp, ...usageBar(i, w)])
  }
  return out
}

/** The whole value or nothing: "5oops" is not a $5 budget. */
export function parseBudget(raw: string | undefined): number | null {
  const t = (raw ?? '').trim()
  const v = /^-?\d+(\.\d+)?$/.test(t) ? Number(t) : null
  return v !== null && Number.isFinite(v) ? v : null
}

const budget = (env: RenderEnv): number => parseBudget(env.CLAUDE_COST_BUDGET) ?? DEFAULT_BUDGET

function segCost(i: RenderInput): Line[] {
  if (i.costUsd === null) return []
  const b = budget(i.env)
  const pct = b <= 0 ? 0 : Math.max(0, roundHalfEven((i.costUsd / b) * 100))
  const out: Line[] = [[grey('💸'), sp, ...pacBar(Math.min(pct, 100), BAR_WIDTH, '•', '$'), sp, { t: `$${i.costUsd.toFixed(2)}`, tone: levelTone(pct) }]]
  if (i.durationMs !== null && i.durationMs > 0) {
    const burn = i.costUsd / (i.durationMs / 3_600_000)
    const bi = roundHalfEven(burn)
    const [tone, emoji]: [Tone, string] = bi >= 20 ? ['red', '🚀'] : bi >= 8 ? ['orange', '🔥'] : ['green', '🐌']
    out.push([{ t: `${emoji} ` }, { t: `$${bi >= 100 ? String(bi) : burn.toFixed(2)}/hr`, tone }])
  }
  return out
}

export function detectAccount(env: RenderEnv): 'personal' | 'work' {
  if (env.CLAUDE_PROFILE) return ['personal', 'home', 'p'].includes(env.CLAUDE_PROFILE) ? 'personal' : 'work'
  if (env.CLAUDE_CONFIG_DIR) return env.CLAUDE_CONFIG_DIR.includes('personal') ? 'personal' : 'work'
  return 'work'
}

export const DEFAULT_MASCOT = '✻'
export const mascot = (env: RenderEnv): string => env.CENSUS_STATUSLINE_MASCOT || DEFAULT_MASCOT

function segModel(i: RenderInput): Line[] {
  const custom = i.env.CENSUS_STATUSLINE_MASCOT
  // The default is a coloured run of its own; an override is drawn as given.
  const glyph: Run = custom ? { t: `${custom} ` } : { t: `${DEFAULT_MASCOT} `, tone: 'claude', bold: true } // bold, and the glyph plus one space: a two-column slot like an emoji
  return [[glyph, ...(custom ? [] : [sp]), { t: i.modelName || 'Claude', tone: 'cyan' }]]
}

function segGit(i: RenderInput): Line[] {
  if (!i.git?.branch) return []
  return [[{ t: `🌿 ${i.git.branch}`, tone: 'green' }]]
}

function segDir(i: RenderInput): Line[] {
  const parts = i.cwd.split(/[\\/]/)
  const shown = parts.length <= 3 ? i.cwd : `…${parts.slice(-3).map(p => `/${p}`).join('')}`
  return [[{ t: `📁 ${shown}`, tone: 'magenta' }]]
}

function segChanges(i: RenderInput): Line[] {
  if (!i.git?.branch) return []
  const line: Line = [{ t: `✏️ ${i.git.uncommitted}`, tone: 'yellow' }]
  if (i.git.ahead > 0 && i.git.hasUpstream) line.push({ t: '  ' }, { t: `⬆️ ${i.git.ahead}`, tone: 'yellow' })
  return [line]
}

const REVIEW_TONE: Record<string, Tone> = { approved: 'green', pending: 'yellow', changes_requested: 'red' }

/** The branch's open PR (from tool events, else the gh cache): `🔀 #12 approved`, the state coloured, all grey when unconfirmed; hidden without one. */
function segPr(i: RenderInput): Line[] {
  if (!i.pr || !(i.pr.number > 0)) return []
  if (i.pr.stale) return [[{ t: `🔀 #${i.pr.number}${i.pr.reviewState ? ` ${i.pr.reviewState}` : ''}`, tone: 'grey' }]] // unconfirmed: dimmed
  const line: Line = [{ t: `🔀 #${i.pr.number}` }]
  if (i.pr.reviewState) line.push(sp, { t: i.pr.reviewState, tone: REVIEW_TONE[i.pr.reviewState] ?? 'grey' })
  return [line]
}

// ---- Clean: one plain line, `🤖 Opus 5.5 | 🧠 85k/200k 42% | 💵 $1.37 | 🕔 5h 38% 0.8x | 🗓️ 7d 12% 0.7x` ----------------

/** 85000 -> 85k, 1000000 -> 1M, 1250000 -> 1.3M. */
export function fmtTokens(n: number): string {
  if (n >= 1_000_000) return `${String(Math.round((n / 1_000_000) * 10) / 10)}M`
  if (n >= 1000) return `${Math.round(n / 1000)}k`
  return String(Math.round(n))
}

/** used% over the share of the window gone (resets_at is when it ends); null when under 1% has gone or the reset is not inside the window. */
export function paceMultiplier(usedPct: number, resetsAt: number, windowSec: number, now: number): number | null {
  const elapsed = 1 - (resetsAt - now) / windowSec
  if (!(elapsed >= 0.01) || elapsed > 1) return null
  return usedPct / (elapsed * 100)
}

const CLEAN_SEPARATOR: Run = { t: ' | ', tone: 'grey' }

function cleanWindow(i: RenderInput, key: 'five_hour' | 'seven_day', emoji: string, label: string, windowSec: number, withPace = true): Run[] | null {
  const w = i.limits[key]
  if (!w || w.resets_at <= i.now) return null // absent, or an expired window: a fossil
  const shown = roundHalfEven(w.used_percentage)
  const pace = withPace ? paceMultiplier(w.used_percentage, w.resets_at, windowSec, i.now) : null
  return [{ t: `${emoji} ${label} ` }, { t: `${shown}%`, tone: levelTone(shown) }, ...(pace === null ? [] : [{ t: ` ${pace.toFixed(1)}x` }])]
}

const cleanLine = (parts: Run[][]): Line[] => (parts.length ? [parts.flatMap((p, k) => (k === 0 ? p : [CLEAN_SEPARATOR, ...p]))] : [])

/** Clean Minimal: `🧠 42% | 🕔 5h 38% | 🗓️ 7d 12%`, no model, cost or multipliers. */
function segCleanMin(i: RenderInput): Line[] {
  const parts: Run[][] = []
  if (i.ctxPct !== null) {
    const shown = roundHalfEven(i.ctxPct)
    parts.push([{ t: '🧠 ' }, { t: `${shown}%`, tone: levelTone(shown) }])
  }
  for (const w of [cleanWindow(i, 'five_hour', '🕔', '5h', 5 * 3600, false), cleanWindow(i, 'seven_day', '🗓️', '7d', 7 * 86400, false)]) if (w) parts.push(w)
  return cleanLine(parts)
}

/** Clean's second line: `📁 pip-skills | 🌿 feat/x +2 ~3 | 🔀 #187 approved`; what is absent goes, separator with it. */
function segCleanWhere(i: RenderInput): Line[] {
  const parts: Run[][] = [[{ t: `📁 ${i.cwd.split(/[\\/]/).filter(Boolean).at(-1) ?? i.cwd}`, tone: 'magenta' }]]
  if (i.git?.branch) {
    const ahead = i.git.ahead > 0 && i.git.hasUpstream ? ` +${i.git.ahead}` : ''
    const dirty = i.git.uncommitted > 0 ? ` ~${i.git.uncommitted}` : ''
    parts.push([{ t: `🌿 ${i.git.branch}${ahead}${dirty}`, tone: 'green' }])
  }
  if (i.pr && i.pr.number > 0) {
    const pr: Run[] = [i.pr.stale ? { t: `🔀 #${i.pr.number}`, tone: 'grey' } : { t: `🔀 #${i.pr.number}` }] // unconfirmed: dimmed
    if (i.pr.reviewState) pr.push({ t: ` ${i.pr.reviewState}`, tone: i.pr.stale ? 'grey' : REVIEW_TONE[i.pr.reviewState] ?? 'grey' })
    parts.push(pr)
  }
  return cleanLine(parts)
}

function segClean(i: RenderInput): Line[] {
  const parts: Run[][] = [[{ t: '🤖 ' }, { t: i.modelName || 'Claude', tone: 'cyan' }]]
  if (i.ctxPct !== null) {
    const shown = roundHalfEven(i.ctxPct)
    const size = i.ctxWindow && i.ctxWindow > 0 ? i.ctxWindow : null
    // The engine reports a percentage and the window, not a token count: used is their product.
    parts.push([{ t: `🧠 ${size ? `${fmtTokens((i.ctxPct / 100) * size)}/${fmtTokens(size)} ` : ''}` }, { t: `${shown}%`, tone: levelTone(shown) }])
  }
  if (i.costUsd !== null) parts.push([{ t: `💵 $${i.costUsd.toFixed(2)}` }])
  for (const w of [cleanWindow(i, 'five_hour', '🕔', '5h', 5 * 3600), cleanWindow(i, 'seven_day', '🗓️', '7d', 7 * 86400)]) if (w) parts.push(w)
  return cleanLine(parts)
}

export const SEGMENTS: Record<string, (i: RenderInput) => Line[]> = {
  context: segContext, cache: segCache, limits: segLimits, cost: segCost, model: segModel, clean: segClean, cleanmin: segCleanMin, cleanwhere: segCleanWhere, git: segGit, dir: segDir, changes: segChanges, pr: segPr,
}

/** The configured segments as lines of names; `/` starts a new line, unknown names are dropped. */
export function layout(spec: string | undefined): string[][] {
  const text = spec?.trim() || DEFAULT_SEGMENTS
  return text.split('/').map(line => line.split(',').map(s => s.trim()).filter(n => Object.hasOwn(SEGMENTS, n)))
}

const SEPARATOR: Run = { t: ' │ ', tone: 'grey' }

/** Each configured line as runs, parts joined by the grey bar; an empty line is dropped. */
export function draw(i: RenderInput): Line[] {
  const lines: Line[] = []
  for (const names of layout(i.env.CENSUS_STATUSLINE_SEGMENTS)) {
    const parts = names.flatMap(n => (Object.hasOwn(SEGMENTS, n) ? SEGMENTS[n]?.(i) : undefined) ?? [])
    if (parts.length) lines.push(parts.flatMap((p, k) => (k === 0 ? p : [SEPARATOR, ...p])))
  }
  return lines
}

export const plain = (line: Line): string => line.map(r => r.t).join('')

/** Terminal columns a string takes: wide emoji and CJK count 2, a variation selector widens its base. */
export function displayWidth(text: string): number {
  let w = 0
  let joined = false // after a zero-width joiner the next emoji is part of the same grapheme
  for (const ch of text) {
    const cp = ch.codePointAt(0) ?? 0
    if (joined) {
      joined = false
      if (cp >= 0x1f000 || WIDE_BMP.has(cp) || cp === 0x2640 || cp === 0x2642 || cp === 0x2695 || cp === 0x2764) continue
    }
    if (cp === 0x200d) joined = true
    if (cp === 0xfe0f) w += 1
    else if (cp === 0x200d || (cp >= 0x300 && cp <= 0x36f)) w += 0
    else if (cp >= 0x1f000 || (cp >= 0x2e80 && cp <= 0xa4cf) || (cp >= 0xac00 && cp <= 0xd7a3) || (cp >= 0xff00 && cp <= 0xff60) || WIDE_BMP.has(cp)) w += 2
    else w += 1
  }
  return w
}
const WIDE_BMP = new Set([0x231a, 0x231b, 0x23e9, 0x23ea, 0x23eb, 0x23ec, 0x23f0, 0x23f3, 0x2614, 0x2615, 0x26a1, 0x2705, 0x270a, 0x270b, 0x2728, 0x274c, 0x2753, 0x2754, 0x2755, 0x2757, 0x2b50, 0x2b55])
export const lineWidth = (line: Line): number => displayWidth(plain(line))

/** Drop whole trailing parts until the line fits `columns`; a lone part is kept (the surface truncates it). */
export function fit(line: Line, columns: number): Line {
  const parts: Line[] = [[]]
  const seps: Run[] = []
  for (const r of line) {
    if (r === SEPARATOR || r === CLEAN_SEPARATOR) {
      parts.push([])
      seps.push(r)
    } else parts[parts.length - 1]?.push(r)
  }
  const join = () => parts.flatMap((p, k) => (k === 0 ? p : [seps[k - 1] ?? SEPARATOR, ...p]))
  while (parts.length > 1 && lineWidth(join()) > columns) {
    parts.pop()
    seps.pop()
  }
  return join()
}

